public class PaymentValidator {
    // Linear validation for transaction chain
    public static boolean validateTransactionChain(List<Transaction> chain) {
        for (Transaction current : chain) {
            // Check if current transaction is valid
            if (!current.isValid()) {
                return false;
            }
        }
        return true;
    }

    // Wrapper method
    public static boolean validate(List<Transaction> chain) {
        if (chain == null || chain.isEmpty()) {
            return false;
        }
        return validateTransactionChain(chain);
    }
}
